        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetHapticGain">SDL_SetHapticGain</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Input.HapticDevice.Features">Features</see></seealso>
        public static extern void SetHapticGain();

        /// <summary>
        /// <para>Stop the haptic effect on its associated haptic device.</para>
        /// </summary>
        /// <param name="haptic">the <c>SDL_Haptic</c> device to stop the effect on.</param>
        /// <param name="effect">the ID of the haptic effect to stop.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_StopHapticEffect">SDL_StopHapticEffect</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Input.HapticDevice.RunEffect">RunEffect</see></seealso>
        /// <seealso><see cref="CSDL.Input.HapticDevice.StopEffects">StopEffects</see></seealso>
        public static extern void StopHapticEffect();

        /// <summary>
        /// <para>Stop all the currently playing effects on a haptic device.</para>
        /// </summary>
        /// <param name="haptic">the <c>SDL_Haptic</c> device to stop.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_StopHapticEffects">SDL_StopHapticEffects</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Input.HapticDevice.RunEffect">RunEffect</see></seealso>
        /// <seealso><see cref="CSDL.Input.HapticDevice.StopEffect">StopEffect</see></seealso>
        public static extern void StopHapticEffects();

        /// <summary>
        /// <para>Stop the simple rumble on a haptic device.</para>
        /// </summary>
        /// <param name="haptic">the haptic device to stop the rumble effect on.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_StopHapticRumble">SDL_StopHapticRumble</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Input.HapticDevice.PlayRumble">PlayRumble</see></seealso>
        public static extern void StopHapticRumble();

        /// <summary>
        /// <para>Update the properties of an effect.</para>
        /// </summary>
        /// <remarks>
        /// <para>Can be used dynamically, although behavior when dynamically changing direction may be strange. Specifically the effect may re-upload itself and start playing from the start. You also cannot change the type either when running <see cref="UpdateHapticEffect"/>.</para>
        /// </remarks>
        /// <param name="haptic">the <c>SDL_Haptic</c> device that has the effect.</param>
        /// <param name="effect">the identifier of the effect to update.</param>
        /// <param name="data">an <see cref="CSDL.Input.HapticEffect">HapticEffect</see> structure containing the new effect properties to use.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_UpdateHapticEffect">SDL_UpdateHapticEffect</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Input.HapticDevice.CreateEffect">CreateEffect</see></seealso>
        /// <seealso><see cref="CSDL.Input.HapticDevice.RunEffect">RunEffect</see></seealso>
        public static extern void UpdateHapticEffect();
    }
}
